const anatomyStudy={id:'vitruvian',name:'Vitruvian Valkrai',role:'Fictional wing anatomy study',asset:'assets/vitruvian-valkrai-v01.png',notes:'Original fictional wing-girdle illustration. Not a human flight model or biological feasibility result.',colors:[]};
const asset=s=>s.asset;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function swatches(){return ''}
document.getElementById('versions').innerHTML=studies.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.slots.map(x=>esc(x.id+' · '+x.title)).join('<br>')}</td><td>${esc([...new Set(s.slots.flatMap(x=>x.aliases))].join(' / '))}</td><td>${esc(s.version)} · Provisional<br>User acceptance unconfirmed</td></tr>`).join('');
for(const id of ['select-a','select-b'])document.getElementById(id).innerHTML=studies.map(s=>`<option value="${s.id}">${esc(s.name)} · ${esc(s.code)}</option>`).join('');document.getElementById('select-b').value='brynhildr';
function renderComparison(){document.getElementById('comparison').innerHTML=['select-a','select-b'].map(id=>studies.find(s=>s.id===document.getElementById(id).value)).map(s=>`<figure><button class="art-button compare-art" data-inspect="${s.id}" aria-label="Inspect ${esc(s.name)}"><img src="${s.asset}" loading="lazy" alt="${esc(s.name)} provisional concept ${s.version}"></button><figcaption>${esc(s.name)}<span>${esc(s.code+' / '+s.version)}</span></figcaption><p class="compare-notes">${esc(s.notes)}</p></figure>`).join('')};renderComparison();for(const id of ['select-a','select-b'])document.getElementById(id).addEventListener('change',renderComparison);
document.getElementById('roster-search').addEventListener('input',e=>{const q=e.target.value.toLocaleLowerCase();let n=0;document.querySelectorAll('#cards .card').forEach(c=>{c.hidden=!c.textContent.toLocaleLowerCase().includes(q);if(!c.hidden)n++});document.getElementById('search-count').textContent=n+' of 24 concept groups';});
const dialog=document.getElementById('inspector'),stage=document.getElementById('stage'),pic=document.getElementById('inspect-image'),zoom=document.getElementById('zoom');let scale=1,x=0,y=0,drag=null;
function transform(){stage.style.setProperty('--scale',scale);stage.style.setProperty('--x',x+'px');stage.style.setProperty('--y',y+'px');zoom.value=String(scale);document.getElementById('zoom-value').textContent=Math.round(scale*100)+'%'}
function setView(view){scale=view==='sheet'?1:2.15;x=view==='folded'?-stage.clientWidth*.23:0;y=view==='folded'?-stage.clientHeight*.23:view==='spread'?stage.clientHeight*.21:0;transform();document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)))}
function inspect(id){const s=[...studies,anatomyStudy].find(s=>s.id===id);pic.src=asset(s);pic.alt=`${s.name} provisional concept sheet ${s.version||'v01'}`;document.getElementById('inspect-title').textContent=s.name;document.getElementById('inspect-role').textContent=s.role;document.getElementById('inspect-notes').textContent=s.notes;document.getElementById('inspect-palette').innerHTML=s.colors.map(c=>`<div class="palette-row"><span class="palette-dot" style="--swatch:${c[1]}"></span>${c[0]} · ${c[1].toUpperCase()}</div>`).join('');document.getElementById('original').href=asset(s);dialog.showModal();setView('sheet')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-inspect]');if(b)inspect(b.dataset.inspect)});document.getElementById('close-inspector').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{drag=null});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));document.getElementById('reset-view').onclick=()=>setView('sheet');zoom.oninput=()=>{scale=Number(zoom.value);transform()};stage.addEventListener('pointerdown',e=>{drag={id:e.pointerId,x:e.clientX,y:e.clientY,ox:x,oy:y};stage.setPointerCapture(e.pointerId)});stage.addEventListener('pointermove',e=>{if(drag&&e.pointerId===drag.id){x=Math.max(-stage.clientWidth,Math.min(stage.clientWidth,drag.ox+e.clientX-drag.x));y=Math.max(-stage.clientHeight,Math.min(stage.clientHeight,drag.oy+e.clientY-drag.y));transform()}});for(const type of ['pointerup','pointercancel','lostpointercapture'])stage.addEventListener(type,()=>{drag=null});stage.addEventListener('keydown',e=>{const dirs={ArrowLeft:[24,0],ArrowRight:[-24,0],ArrowUp:[0,24],ArrowDown:[0,-24]};if(dirs[e.key]){e.preventDefault();x+=dirs[e.key][0];y+=dirs[e.key][1];transform()}if(e.key==='Home')setView('sheet')});
